def verdopple(x: int) -> int:
    return x * 2

print(verdopple(4))     # 8
print(verdopple("ab"))  # abab  (!)

def schnitt(noten: list[int]) -> float:
    return sum(noten) / len(noten)

def suche(d: dict[str, int],
          name: str) -> int | None:
    return d.get(name)

print(schnitt([1, 2, 2, 3]))      # 2.0
print(suche({"Anna": 2}, "Ben"))  # None

from typing import Generic, TypeVar

T = TypeVar("T")

class Stapel(Generic[T]):
    def __init__(self) -> None:
        self._daten: list[T] = []

    def push(self, x: T) -> None:
        self._daten.append(x)

    def pop(self) -> T:
        return self._daten.pop()

s: Stapel[int] = Stapel()
s.push(5)
s.push(7)
print(s.pop())   # 7

